import React, { useState, useEffect } from 'react';
import Dashboard from './components/Dashboard';
import AddRecord from './components/AddRecord';
import RecordsList from './components/RecordsList';
import { getAllFuelRecords, deleteFuelRecord, initDB, exportRecordsJSON, importRecordsJSON } from './utils/database';
import { initGoogle, signIn, signOut, isSignedIn, uploadBackup, downloadBackup } from './utils/driveSync';
import './App.css';
import { FiBarChart2, FiPlusCircle, FiList, FiMoon, FiSun } from 'react-icons/fi';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState(() => {
    const stored = localStorage.getItem('fuelio-theme');
    return stored || 'light';
  });
  const [syncStatus, setSyncStatus] = useState('idle'); // idle | auth | syncing | error | done
  const [driveReady, setDriveReady] = useState(false);

  useEffect(() => {
    loadRecords();
    // Initialize Google Identity Services (async)
    initGoogle().then(ready => {
      setDriveReady(ready);
    });
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('fuelio-theme', theme);
  }, [theme]);

  const loadRecords = async () => {
    try {
      await initDB();
      const allRecords = await getAllFuelRecords();
      setRecords(allRecords);
    } catch (error) {
      console.error('Error loading records:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleRecordAdded = () => {
    loadRecords();
    setActiveTab('dashboard');
  };

  const handleDeleteRecord = async (id) => {
    if (window.confirm('Are you sure you want to delete this record?')) {
      try {
        await deleteFuelRecord(id);
        loadRecords();
      } catch (error) {
        console.error('Error deleting record:', error);
        alert('Failed to delete record. Please try again.');
      }
    }
  };

  const handleGoogleAuth = async () => {
    if (!driveReady) {
      alert('Google services are still loading, please wait...');
      return;
    }
    if (isSignedIn()) {
      signOut();
      setSyncStatus('idle');
      return;
    }
    setSyncStatus('auth');
    try {
      await signIn();
      setSyncStatus('idle');
    } catch (e) {
      console.error(e);
      alert('Sign in failed: ' + e.message);
      setSyncStatus('error');
    }
  };

  const handleBackupUpload = async () => {
    if (!isSignedIn()) return alert('Sign in with Google first');
    setSyncStatus('syncing');
    try {
      const json = await exportRecordsJSON();
      await uploadBackup(json);
      setSyncStatus('done');
      setTimeout(() => setSyncStatus('idle'), 2500);
    } catch (e) {
      console.error(e);
      setSyncStatus('error');
    }
  };

  const handleBackupDownload = async () => {
    if (!isSignedIn()) return alert('Sign in with Google first');
    setSyncStatus('syncing');
    try {
      const jsonText = await downloadBackup();
      const updated = await importRecordsJSON(jsonText);
      setRecords(updated);
      setSyncStatus('done');
      setTimeout(() => setSyncStatus('idle'), 2500);
    } catch (e) {
      console.error(e);
      setSyncStatus('error');
    }
  };

  const getLastOdometer = () => {
    if (records.length === 0) return null;
    const sortedRecords = [...records].sort((a, b) => b.odometer - a.odometer);
    return sortedRecords[0].odometer;
  };

  if (loading) {
    return (
      <div className="app-loading">
        <div className="spinner-large"></div>
        <p>Loading Fuelio...</p>
      </div>
    );
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="header-content">
          <div>
            <h1 className="app-logo">Fuelio</h1>
            <p className="app-tagline">Smart Fuel Efficiency Tracker</p>
          </div>
          <div className="header-actions">
            <button className="nav-button nav-button-compact" onClick={handleGoogleAuth}>
              {isSignedIn() ? '🔓 Sign Out' : '🔒 Sign In'}
            </button>
            {isSignedIn() && (
              <>
                <button className="nav-button nav-button-compact" onClick={handleBackupUpload} disabled={syncStatus==='syncing'}>
                  ↥ Backup
                </button>
                <button className="nav-button nav-button-compact" onClick={handleBackupDownload} disabled={syncStatus==='syncing'}>
                  ↧ Restore
                </button>
              </>
            )}
            <button
              className="theme-toggle"
              onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
              aria-label="Toggle theme"
            >
              {theme === 'light' ? <FiMoon /> : <FiSun />}
            </button>
          </div>
        </div>
      </header>

      <nav className="app-nav">
        <button
          className={`nav-tab ${activeTab === 'dashboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('dashboard')}
        >
          <FiBarChart2 className="nav-icon" />
          <span className="nav-label">Dashboard</span>
        </button>
        <button
          className={`nav-tab ${activeTab === 'add' ? 'active' : ''}`}
          onClick={() => setActiveTab('add')}
        >
          <FiPlusCircle className="nav-icon" />
          <span className="nav-label">Add</span>
        </button>
        <button
          className={`nav-tab ${activeTab === 'records' ? 'active' : ''}`}
          onClick={() => setActiveTab('records')}
        >
          <FiList className="nav-icon" />
          <span className="nav-label">History</span>
        </button>
      </nav>

      <main className="app-main">
        {activeTab === 'dashboard' && <Dashboard records={records} />}
        {activeTab === 'add' && (
          <AddRecord 
            onRecordAdded={handleRecordAdded}
            lastOdometer={getLastOdometer()}
          />
        )}
        {activeTab === 'records' && (
          <RecordsList 
            records={records}
            onDelete={handleDeleteRecord}
          />
        )}
      </main>

      <footer className="app-footer">
        <p>© 2025 Fuelio - All data stored locally on your device</p>
        {records.length > 0 && (
          <p className="footer-stats">
            📊 {records.length} record{records.length !== 1 ? 's' : ''} stored
          </p>
        )}
        {isSignedIn() && (
          <p className="footer-sync-status">
            Sync: {syncStatus === 'idle' && 'Ready'}
            {syncStatus === 'auth' && 'Authorizing...'}
            {syncStatus === 'syncing' && 'Syncing...'}
            {syncStatus === 'error' && 'Error'}
            {syncStatus === 'done' && 'Completed'}
          </p>
        )}
      </footer>
    </div>
  );
}

export default App;
