// Google Drive sync utilities using Google Identity Services for OAuth
// Scope: Drive file access to app data folder or specific file in user's Drive

const CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;
const SCOPES = 'https://www.googleapis.com/auth/drive.file';
const TOKEN_CLIENT_STATE_KEY = 'fuelio_drive_token';
const BACKUP_FILE_NAME = 'fuelio-backup.json';
const BACKUP_FILE_ID_KEY = 'fuelio_drive_file_id';

let tokenClient = null;
let accessToken = null;

function ensureGisLoaded() {
  if (typeof window === 'undefined') return false;
  return !!window.google && !!window.google.accounts && !!window.google.accounts.oauth2;
}

export function initGoogle() {
  return new Promise((resolve) => {
    if (!CLIENT_ID) {
      console.warn('Google Client ID missing. Set REACT_APP_GOOGLE_CLIENT_ID in .env');
      resolve(false);
      return;
    }

    // If already loaded, init immediately
    if (ensureGisLoaded()) {
      if (!tokenClient) {
        tokenClient = window.google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (_response) => {},
        });
      }
      resolve(true);
      return;
    }

    // Wait for script to load (max 5 seconds)
    let attempts = 0;
    const checkInterval = setInterval(() => {
      attempts++;
      if (ensureGisLoaded()) {
        clearInterval(checkInterval);
        if (!tokenClient) {
          tokenClient = window.google.accounts.oauth2.initTokenClient({
            client_id: CLIENT_ID,
            scope: SCOPES,
            callback: (_response) => {},
          });
        }
        resolve(true);
      } else if (attempts > 50) {
        clearInterval(checkInterval);
        console.error('Google Identity Services failed to load');
        resolve(false);
      }
    }, 100);
  });
}

export async function signIn() {
  const ready = await initGoogle();
  if (!ready) throw new Error('Google Identity Services not initialized');
  return new Promise((resolve, reject) => {
    tokenClient.callback = (resp) => {
      if (resp.error) return reject(resp);
      accessToken = resp.access_token;
      try { localStorage.setItem(TOKEN_CLIENT_STATE_KEY, '1'); } catch {}
      resolve(accessToken);
    };
    tokenClient.requestAccessToken({ prompt: 'consent' });
  });
}

export function signOut() {
  accessToken = null;
  try { localStorage.removeItem(TOKEN_CLIENT_STATE_KEY); } catch {}
}

function getAccessTokenOrThrow() {
  if (accessToken) return accessToken;
  throw new Error('Not authenticated with Google');
}

async function driveRequest(path, options = {}) {
  const token = getAccessTokenOrThrow();
  const resp = await fetch(`https://www.googleapis.com/drive/v3/${path}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${token}`,
      ...(options.headers || {}),
    },
  });
  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`Drive API error ${resp.status}: ${text}`);
  }
  const ct = resp.headers.get('content-type') || '';
  return ct.includes('application/json') ? resp.json() : resp.text();
}

async function uploadMultipartJson(name, jsonString, fileId) {
  const token = getAccessTokenOrThrow();
  const metadata = { name, mimeType: 'application/json' };
  const boundary = '-------314159265358979323846';
  const delimiter = `\r\n--${boundary}\r\n`;
  const closeDelim = `\r\n--${boundary}--`;

  const body =
    delimiter +
    'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
    JSON.stringify(metadata) +
    delimiter +
    'Content-Type: application/json\r\n\r\n' +
    jsonString +
    closeDelim;

  const url = fileId
    ? `https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=multipart`
    : 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart';

  const method = fileId ? 'PATCH' : 'POST';
  const resp = await fetch(url, {
    method,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': `multipart/related; boundary=${boundary}`,
    },
    body,
  });
  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`Upload failed ${resp.status}: ${text}`);
  }
  return resp.json();
}

export async function uploadBackup(jsonString) {
  // Try to reuse existing file ID
  const existingId = localStorage.getItem(BACKUP_FILE_ID_KEY) || null;
  try {
    const file = await uploadMultipartJson(BACKUP_FILE_NAME, jsonString, existingId);
    localStorage.setItem(BACKUP_FILE_ID_KEY, file.id);
    return file;
  } catch (e) {
    // If reuse failed (e.g., 404), try fresh upload
    const file = await uploadMultipartJson(BACKUP_FILE_NAME, jsonString, null);
    localStorage.setItem(BACKUP_FILE_ID_KEY, file.id);
    return file;
  }
}

export async function findBackupFile() {
  // Search by name within user's Drive
  const q = encodeURIComponent(`name = '${BACKUP_FILE_NAME.replace(/'/g, "\\'")}' and trashed = false`);
  const res = await driveRequest(`files?q=${q}&fields=files(id,name,modifiedTime,size)`);
  return res.files && res.files.length ? res.files[0] : null;
}

export async function downloadBackup(fileId) {
  const id = fileId || localStorage.getItem(BACKUP_FILE_ID_KEY);
  if (!id) {
    const found = await findBackupFile();
    if (!found) throw new Error('No backup file found in Drive');
    localStorage.setItem(BACKUP_FILE_ID_KEY, found.id);
    return downloadBackup(found.id);
  }
  const token = getAccessTokenOrThrow();
  const resp = await fetch(`https://www.googleapis.com/drive/v3/files/${id}?alt=media`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!resp.ok) throw new Error(`Download failed ${resp.status}`);
  return resp.text();
}

export function isSignedIn() {
  return !!accessToken;
}

export function getDriveFileId() {
  return localStorage.getItem(BACKUP_FILE_ID_KEY);
}
